        match self {
            OrderBy::Scalar(o) => o.sort_order,
            OrderBy::ScalarAggregation(o) => o.sort_order,
            OrderBy::ToManyAggregation(o) => o.sort_order,
            OrderBy::Relevance(o) => o.sort_order,
