+pub(crate) struct SelectBuilder;
+
+impl SelectBuilder {
+    pub fn build(args: QueryArguments, selected_fields: &FieldSelection, ctx: &Context<'_>) -> Select<'static> {
+        if supports_lateral_join(&args) {
